mapper.select:
SELECT  FROM cut_assessment
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId} AND id = #{query.assessmentId}
  AND current_marker = 1 AND deleted = 0 FOR UPDATE

mapper.sql:
tenant_id = #{query.assessment.tenantId} AND task_id = #{query.assessment.cutoverTaskId}
AND id = #{query.assessment.id} AND version = #{query.expectedVersion}
AND assessment_status_code = 'DRAFT' AND current_marker = 1 AND deleted = 0

mapper.update:
UPDATE cut_assessment
SET assessment_status_code = 'INVALIDATED', current_marker = NULL,
    invalidate_user_id = #{query.actorId}, invalidate_time = #{query.time}, invalidation_reason = #{query.reason},
    version = version + 1, updater = #{query.actorId}, update_time = #{query.time}
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId} AND id = #{query.sourceId}
  AND version = #{query.expectedVersion} AND assessment_status_code = 'SUBMITTED' AND current_marker = 1 AND deleted = 0
